#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    vector<array<string,3>> restaurantGrowth(vector<vector<string>>& rows) {
        map<string,long long> daily;
        for (auto& r : rows) daily[r[2]] += stoll(r[3]);
        vector<pair<string,long long>> v(daily.begin(), daily.end());
        vector<array<string,3>> res;
        for (int i = 6; i < (int)v.size(); i++) {
            long long s = 0;
            for (int j = i - 6; j <= i; j++) s += v[j].second;
            double avg = round(s / 7.0 * 100) / 100;
            char buf[32]; snprintf(buf, 32, "%.2f", avg);
            res.push_back({v[i].first, to_string(v[i].second), buf});
        }
        return res;
    }
};

