import java.util.*;

class Solution {
    public List<List<String>> restaurantGrowth(List<List<String>> rows) {
        TreeMap<String, Long> daily = new TreeMap<>();
        for (List<String> r : rows)
            daily.merge(r.get(2), Long.parseLong(r.get(3)), Long::sum);
        List<String> dates = new ArrayList<>(daily.keySet());
        List<List<String>> res = new ArrayList<>();
        for (int i = 6; i < dates.size(); i++) {
            long s = 0;
            for (int j = i - 6; j <= i; j++) s += daily.get(dates.get(j));
            double avg = Math.round(s / 7.0 * 100) / 100.0;
            res.add(Arrays.asList(dates.get(i), String.valueOf(daily.get(dates.get(i))),
                    String.format(java.util.Locale.US, "%.2f", avg)));
        }
        return res;
    }
}

