        daily.set(d, (daily.get(d) || 0) + Number(amt));
    const dates = [...daily.keys()].sort();
    const n = dates.length;
    const pre = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) pre[i + 1] = pre[i] + daily.get(dates[i]);
